def choose_move(observation):
    grid_width = observation.get("grid_width", 0)
    grid_height = observation.get("grid_height", 0)
    self_position = observation.get("self_position", {"x": 0, "y": 0})
    opponent_position = observation.get("opponent_position", {"x": 0, "y": 0})
    resources = observation.get("resources", [])
    obstacles = observation.get("obstacles", [])
    remaining_resource_count = observation.get("remaining_resource_count", 0)
    scores = observation.get("scores", {})
    self_path = observation.get("self_path", [])
    opponent_path = observation.get("opponent_path", [])

    x = self_position.get("x", 0)
    y = self_position.get("y", 0)

    def clamp(v):
        if v > 1:
            return 1
        if v < -1:
            return -1
        return int(v)

    # If there is any resource, move towards the closest one
    best = None
    bestd = None
    for r in resources:
        rx = r.get("x", 0)
        ry = r.get("y", 0)
        d = abs(rx - x) + abs(ry - y)
        if bestd is None or d < bestd:
            bestd = d
            best = (rx, ry)

    if best is not None:
        rx, ry = best
        dx = clamp(rx - x)
        dy = clamp(ry - y)
        if dx != 0 and dy != 0:
            if abs(rx - x) >= abs(ry - y):
                dy = 0
            else:
                dx = 0
        return [dx, dy]

    # Otherwise move to reduce distance to opponent while avoiding obstacles if possible
    ox = opponent_position.get("x", 0)
    oy = opponent_position.get("y", 0)
    dx = clamp(ox - x)
    dy = clamp(oy - y)

    if dx != 0 and dy != 0:
        if abs(ox - x) >= abs(oy - y):
            dy = 0
        else:
            dx = 0

    # If next step would collide with obstacle, try other axis
    def blocked(nx, ny):
        for ob in obstacles:
            ox2 = ob.get("x", 0)
            oy2 = ob.get("y", 0)
            if nx == ox2 and ny == oy2:
                return True
        return False

    nx = x + dx
    ny = y + dy
    if blocked(nx, ny):
        # try orthogonal move
        alt_dx, alt_dy = -dx, 0
        if dx == 0:
            alt_dx, alt_dy = 0, -dy
        if not blocked(x + alt_dx, y + alt_dy):
            return [alt_dx, alt_dy]
        # try staying or other axis
        if not blocked(x, y):
            return [0, 0]
        # last resort, move to reduce distance to opponent along any available axis
        if dx != 0:
            return [dx, 0]
        if dy != 0:
            return [0, dy]
        return [0, 0]

    return [dx, dy]
